TLM.f("Tempora/Pasc2-4Feria",{"officium":"Feria Quinta infra Hebdomadam II post Octavam Paschæ","rule":["Oratio Dominica","Gloria","no Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc2-0","from":{"Introitus":"Tempora/Pasc2-0","Oratio":"Tempora/Pasc2-0","Lectio":"Tempora/Pasc2-0","Graduale":"Tempora/Pasc2-0","Evangelium":"Tempora/Pasc2-0","Offertorium":"Tempora/Pasc2-0","Secreta":"Tempora/Pasc2-0","Communio":"Tempora/Pasc2-0","Postcommunio":"Tempora/Pasc2-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 32:5-6"},{"k":"text","la":"Misericórdia Dómini plena est terra, allelúja: verbo Dómini cœli firmáti sunt, allelúja, allelúja."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Misericórdia Dómini plena est terra, allelúja: verbo Dómini cœli firmáti sunt, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui in Fílii tui humilitáte jacéntem mundum erexísti: fidélibus tuis perpétuam concéde lætítiam; ut, quos perpétuæ mortis eripuísti cásibus, gáudiis fácias pérfrui sempitérnis."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Petri 2:21-25"},{"k":"text","la":"Caríssimi: Christus passus est pro nobis, vobis relínquens exémplum, ut sequámini vestígia ejus. Qui peccátum non fecit, nec invéntus est dolus in ore ejus: qui cum maledicerétur, non maledicébat: cum paterétur, non comminabátur: tradébat autem judicánti se injúste: qui peccáta nostra ipse pértulit in córpore suo super lignum: ut, peccátis mórtui, justítiæ vivámus: cujus livóre sanáti estis. Erátis enim sicut oves errántes, sed convérsi estis nunc ad pastórem et epíscopum animárum vestrárum."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Luc 24:35"},{"k":"text","la":"Cognovérunt discípuli Dóminum Jesum in fractióne panis. Allelúja"},{"k":"ref","la":"Joannes 10:14"},{"k":"text","la":"Ego sum pastor bonus: et cognósco oves meas, et cognóscunt me meæ. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 10:11-16"},{"k":"text","la":"In illo témpore: Dixit Jesus pharisǽis: Ego sum pastor bonus. Bonus pastor ánimam suam dat pro óvibus suis. Mercenárius autem et qui non est pastor, cujus non sunt oves própriæ, videt lupum veniéntem, et dimíttit oves et fugit: et lupus rapit et dispérgit oves: mercenárius autem fugit, quia mercenárius est et non pértinet ad eum de óvibus. Ego sum pastor bonus: et cognósco meas et cognóscunt me meæ. Sicut novit me Pater, et ego agnósco Patrem, et ánimam meam pono pro óvibus meis. Et álias oves hábeo, quæ non sunt ex hoc ovíli: et illas opórtet me addúcere, et vocem meam áudient, et fiet unum ovíle et unus pastor."}],"Offertorium":[{"k":"ref","la":"Ps 62:2; 62:5"},{"k":"text","la":"Deus, Deus meus, ad te de luce vígilo: et in nómine tuo levábo manus meas, allelúja."}],"Secreta":[{"k":"text","la":"Benedictiónem nobis, Dómine, cónferat salutárem sacra semper oblátio: ut, quod agit mystério, virtúte perfíciat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 10:14"},{"k":"text","la":"Ego sum pastor bonus, allelúja: et cognósco oves meas, et cognóscunt me meæ, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Præsta nobis, quǽsumus, omnípotens Deus: ut, vivificatiónis tuæ grátiam consequéntes, in tuo semper múnere gloriémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"6ec5ef5b01f9ccc7":{"t":"Ps 32, 5-6, Ps 32, 1\n(Ps 32, 5-6) Milosrđa je Gospodnjega puna zemlja, <i>aleluja</i>!\nRiječju su Gospodnjom utvrđena nebesa, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 32, 1). Radujte se, pravednici, u Gospodinu, dobrima dolikuje da ga hvale.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 32, 5-6) Milosrđa je Gospodnjega puna zemlja, <i>aleluja</i>!\nRiječju su Gospodnjom utvrđena nebesa, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 32, 5-6). Milosrđa je Gospodnjega puna zemlja; riječju Gospodnjom utvrđena su nebesa, aleluja, aleluja (Ps. 32, 1). Radujte se, pravednici, u Gospodinu, čestitima dolikuje pohvala. Slava Ocu ... Milosrđa ...","knRef":"Kniewald 1942, str. 318–319 (snimka 160) (OCR)"},"9b054e1ad1cc6d88":{"t":"<i>Pomolimo se</i>.\nBože, koji si poniženjem svoga Sina podigao oboreno čovječanstvo, daj svojim vjernicima da se uvijek raduju tako, da onima koje si izbavio od vječne propasti dadeš uživati vječno veselje.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si poniznošću Sina svojega podigao oboreni svijet, dopusti vjernicima svojim vječno veselje i učini, da uživaju v jek ovite radosti, koje si izbavio od nevolja vječne smrti, po istom G. n.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"4e98e768a529d23e":{"t":"1 Pt 2, 21-25\nČitanje Poslanice bl. Petra apostola. Predragi: Krist je trpio za nas i ostavio vam primjer, da idete njegovim stopama. On ne učini grijeha i u njegovim se ustima ne nađe prijevare. Kad su ga grdili, nije uzvraćao grdnjom, kad je trpio, nije prijetio, nego se prepustio onome koji jedini sudi pravedno. On je na svom vlastitom tijelu ponio naše grijehe na križ, da mi umrvši grijehu živimo za pravdu. Izliječili ste se njegovim ranama. Bili ste kao zalutale ovce, ali ste se sada obratili k pastiru i čuvaru vaših duša.","kn":"Čitanje poslanice bi. Petra apostola (I, 2, 21-25). Predragi! Krist, koji ne učini grijeha niti se nađe prijevara u njegovim ustima, trpio je za nas 1 ostavio vam primjer, da slijedite njegove stope. Kad su ga psovali, nije uzvraćao psovkom, kad je trpio, nije prijetio, nego se predao u ruke onomu, koji ga je sudio nepravedno. Na svojemu tijelu ponese naše grijehe na drvo, da umremo grijesima, a živimo pravdi. Izliječili ste se njegovom modricom. Jer ste bili kao zalutale ovce, sada ste se obratili k pastiru i čuvaru svojih duša.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"6c602ad1560ff6bf":{"t":"Lk 24, 35, Iv 10, 14\n<i>Aleluja</i>, <i>aleluja</i>.\n(Lk 24, 35) Učenici su prepoznali Gospodina Isusa po lomljenju kruha, <i>aleluja</i>.\n(Iv 10, 14) Ja sam dobri pastir i poznajem svoje ovce, a moje ovce poznaju mene, <i>aleluja</i>.","kn":"Aleluja, aleluja (Lk. 24, 35). Prepoznali su učenici Gospodina u lomljenju kruha, aleluja. (Iv. 10. 14) Ja sam dobri pastir- 1 poznajem svoje ovce, a one, koje su moje, poznaju mene, aleluja.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"24aa582fd8f56d69":{"t":"Iv 10, 11-16\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: reče Isus farizejima: Ja sam dobri pastir. Dobar pastir daje svoj život za svoje ovce, a najamnik, koji nije pastir i nije vlasnik ovaca, kad vidi da dolazi vuk, ostavi ovce i bježi, pa vuk grabi i razgoni ovce. Najamnik bježi, jer je najamnik i nije mu stalo do ovaca. Ja sam dobri pastir i poznajem svoje ovce, a moje ovce poznaju mene, kao što Otac poznaje mene i kao što ja poznajem Oca. I ja dajem svoj život za svojeg ovce. Imam i drugih ovaca, koje nisu iz ovog ovčinjaka. I njih mi treba dovesti i čut će moj glas i bit će jedno stado i jedan pastir.","kn":"t Slijedi sveto evanđelje po Ivanu (10, 11-16). U ono vrijeme reče Isus farizejima: Ja sam dobri pastir. Dobri pastir polaže svoji život za svoje .ovce. A najamnik, koji nije pastir, koji nema svojih ovaca, kad vidi, da dolazi vuk, ostavlja o-vce i bježi, a vuk ih grabi 1 razgoni. Najamnik bježi jer je najamnik i nije mu stalo do ovaca. Ja sam dobri pastir i poznajem svoje ovce, a moje poznaju mene. Ka-o što mene poznaje Otac, i ja poznajem Oca, i svoj život polažem za svoje ovce. Imam i drugih ovaca, koje nijesu iz ovog ovčinjaka. Ali i one Sv. Josip, zaštitnik sv. Crkve treba da dovedem, i slušat će moj glas i bit će jedno stado 1 jedan pastir.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"4119f0bfe80dd6b4":{"t":"Ps 62, 2 i 5\nBože, Bože moj, pred tobom bdijem od svanuća, i u tvoje ću ime dizati svoje ruke, <i>aleluja</i>.","kn":"(Ps. 62, 2, 5). Bože, Bože moj, k Tebi rano ranim i u Tvoje ime dižem ruke svoje, aleluja.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"1a11a54401cf57f1":{"t":"Sveti prinos, Gospodine, neka nam uvijek donese spasonosni blagoslov, da svojom snagom dovrši ono što otajstveno predstavlja.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Sveti prinos neka nam. Gospodine, vazda prinese spasonosni blagoslov, da krepošću izvrši, što čini otajstvom, po G. n.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"ca3dcc6d74e17a81":{"t":"Iv 10, 14\nJa sam dobri pastir <i>aleluja</i>,\ni poznam svoje ovce, a moje ovce poznaju mene, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 10, 14). Ja sam pastir dobri i poznajem ovce moje i one, koje su moje, poznaju mene, aleluja, aleluja.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"},"196c09cf5177e8ff":{"t":"<i>Pomolimo se</i>.\nPodaj nam, molimo, svemogući Bože, da se uvijek dičimo tvojim darom mi koji smo primili tvoju milost novog života.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, molimo, svemogući Bože, da se vazda hvalimo; Tvojim darom, kojim smo dostigli milost novoga života u Tebi, po G. n.","knRef":"Kniewald 1942, str. 320–321 (snimka 161) (OCR)"}}});
